import{$ as e,B as t,o as n,z as r}from"./chunks/framework.BROBN02c.js";var i=JSON.parse(`{"title":"Embedded mirror & key mapping","description":"","frontmatter":{"title":"Embedded mirror & key mapping"},"headers":[],"relativePath":"guide/mirror.md","filePath":"en/guide/mirror.md","lastUpdated":1795479642000}`),a={name:`guide/mirror.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="embedded-mirror-key-mapping" tabindex="-1">Embedded mirror &amp; key mapping <a class="header-anchor" href="#embedded-mirror-key-mapping" aria-label="Permalink to &quot;Embedded mirror &amp; key mapping&quot;">​</a></h1><p>The embedded mirror renders the device screen inside an Escrcpy window instead of a native scrcpy window, which makes it possible to overlay keyboard mappings, always-on-top and fullscreen. Video is hardware-decoded with WebCodecs; audio is played through Web Audio.</p><h2 id="opening" tabindex="-1">Opening <a class="header-anchor" href="#opening" aria-label="Permalink to &quot;Opening&quot;">​</a></h2><ol><li>Find the device in the device list</li><li>Click the &quot;more&quot; (＋) button on the row</li><li>Choose &quot;Embedded mirror&quot;</li></ol><p>The window remembers its previous size and position. The header shows the device name, resolution, fps, audio toggle, key mapping, always-on-top, fullscreen and close.</p><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><ul><li><strong>Mouse / touch</strong>: left button drags a touch pointer; multi-touch is supported (each pointer maps to its own contact)</li><li><strong>Wheel</strong>: scrolls the device; with a &quot;scroll&quot; mapping enabled it becomes a pinch gesture</li><li><strong>Keyboard</strong>: physical keys map to Android key events; text (Chinese, emoji, …) is injected as text</li><li><strong>Esc</strong>: back; the clipboard is synced to the device when the window gains focus</li><li><strong>Right click</strong>: back (in edit mode it adds a mapping instead)</li></ul><h2 id="keyboard-mapping" tabindex="-1">Keyboard mapping <a class="header-anchor" href="#keyboard-mapping" aria-label="Permalink to &quot;Keyboard mapping&quot;">​</a></h2><p>Open the mapping panel with the grid icon in the header, then switch modes at the top of the panel:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td>Off</td><td>No mappings, plain touch only</td></tr><tr><td>Edit</td><td>Right-click the picture to add mappings, drag nodes, tune parameters</td></tr><tr><td>Play</td><td>Pressing a bound key triggers its mapped gesture</td></tr></tbody></table><h3 id="adding-a-mapping" tabindex="-1">Adding a mapping <a class="header-anchor" href="#adding-a-mapping" aria-label="Permalink to &quot;Adding a mapping&quot;">​</a></h3><ol><li>Switch to &quot;Edit&quot;</li><li>Right-click the picture → a tap mapping is created there</li><li>Select it, click &quot;Bind key&quot; and press a key combination (Esc cancels)</li><li>Pick the mapping type and adjust its parameters below</li></ol><p>Supported types: tap, swipe, rapid tap, scroll (wheel → pinch), joystick (WASD directions inside a radius), view control (mouse look) and macro (run an existing automation workflow, with a loop count).</p><h3 id="profiles" tabindex="-1">Profiles <a class="header-anchor" href="#profiles" aria-label="Permalink to &quot;Profiles&quot;">​</a></h3><p>Mappings are stored per device in profiles. Use the panel header to create / duplicate / delete profiles; import / export uses JSON files so mappings can move between machines.</p><h2 id="visual-workflow-editor" tabindex="-1">Visual workflow editor <a class="header-anchor" href="#visual-workflow-editor" aria-label="Permalink to &quot;Visual workflow editor&quot;">​</a></h2><p>&quot;Tasks → Workflows → New workflow&quot; is now a node canvas:</p><ul><li>Start → steps → End, connected automatically</li><li>Drag nodes to reposition; drop a node onto another to insert it at that position</li><li>Zoom / fit / auto-layout toolbar; Ctrl + wheel zooms, drag the background to pan</li><li>The inspector on the right edits the selected step (AI / action / delay)</li><li>Shortcuts: Delete removes the selected step, Ctrl + D duplicates it</li></ul><h2 id="web-ui" tabindex="-1">Web UI <a class="header-anchor" href="#web-ui" aria-label="Permalink to &quot;Web UI&quot;">​</a></h2><p>With the web UI enabled, a new &quot;Mirror&quot; tab lets you pick a device and connect. The stream is pushed over SSE and decoded by the browser&#39;s WebCodecs; touch, keyboard, wheel, clipboard and key mappings (tap mappings + key binding) are supported. The tasks page also renders each workflow as a visual chain with a one-click run button.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};